// Points the model at lookup where it would otherwise pull a whole page or output into context, and
// keeps lookup's and view's schemas in the prompt's list so they are called without a ToolSearch first.
import type { On } from 'claude-code'

// Constant on purpose: the describe answer is cached per session and any change spends the prompt cache.
export const NOTE =
  "\n\nFor one fact about a page or a command's output, call mcp__slim__lookup({ url | command | path, question }) — " +
  'it returns a short answer instead of the whole output.'

export function registerDescribe(on: On): void {
  on('tool.describe', { tool: /^(?:Bash|WebFetch)$/ }, async ($, e, next) => {
    if ((await $.env.get('SLIM_LOOKUP')) === '0') return next(e)
    const d = await next(e)
    return { ...d, description: d.description + NOTE }
  })

  on('tool.describe', { tool: 'mcp__slim__lookup' }, async ($, e, next) => {
    if ((await $.env.get('SLIM_LOOKUP')) === '0') return next(e)
    return { ...(await next(e)), isDeferred: false }
  })

  on('tool.describe', { tool: 'mcp__slim__view' }, async (_$, e, next) => ({ ...(await next(e)), isDeferred: false }))
}

files.hooks/mods/eventlog.ts:
// slim.jsonl: every line slim publishes to slim.events also goes to this session's file on disk,
// `<dir>/<session-id>/slim.jsonl`, one JSON object per line, rewritten whole after each. The file follows
// the list through slim's own state.set hook, so SLIM_EVENT_LOG=0, which stops the list, stops the file.
import type { EngineInterface, On } from 'claude-code'
import type { SlimEvent } from '../../types'
import { agentLabel } from './events.ts'
import { utf8Bytes } from './node-hook.ts'

type $ = EngineInterface

export const FILE_LINES = 2000
export const FILE_BYTES = 256 * 1024

/** `$DOMAINE_LOG_DIR/<session>` when the override is absolute, else `$HOME/.claude/domaine/log/<session>`; null with neither. */
export function logDir(home: string | undefined, override: string | undefined, session: string): string | null {
  if (!/^[\w.-]+$/.test(session) || /^\.+$/.test(session)) return null
  const o = override?.trim() ?? ''
  const h = home?.trim() ?? ''
  const base = o.startsWith('/') ? o.replace(/\/+$/, '') : h.startsWith('/') ? `${h.replace(/\/+$/, '')}/.claude/domaine/log` : null
  return base === null ? null : `${base}/${session}`
}

/** One slim.jsonl line; `agent` is the subagent type slim labels the event's text with, else `main`. */
export function fileLine(ev: SlimEvent, version: string, session: string): string {
  const type = 'agentType' in ev ? ev.agentType : undefined
  return JSON.stringify({
    ts: new Date(ev.atMs).toISOString(),
    plugin: 'slim',
    version,
    session,
    kind: ev.kind,
    agent: type ? agentLabel(type) : 'main',
    text: ev.text,
  })
}

/** A session's lines, oldest first, and their bytes in the file (each line plus its newline). */
export type Kept = { lines: string[]; bytes: number }

/** Appends `line`, dropping the oldest past FILE_LINES lines or FILE_BYTES bytes; the newest line always stays. */
export function keep(k: Kept, line: string): void {
  k.lines.push(line)
  k.bytes += utf8Bytes(line) + 1
  while (k.lines.length > 1 && (k.lines.length > FILE_LINES || k.bytes > FILE_BYTES)) k.bytes -= utf8Bytes(k.lines.shift()!) + 1
}

/** The newest lines of a file slim wrote that belong to `session` and fit the cap: what a reload goes on from. */
export function seedLines(text: string, session: string): Kept {
  const mine = text.split('\n').filter(l => {
    try {
      return (JSON.parse(l) as { session?: unknown }).session === session
    } catch {
      return false
    }
  })
  let i = mine.length
  let bytes = 0
  while (i > 0 && mine.length - i < FILE_LINES) {
    const b = utf8Bytes(mine[i - 1]!) + 1
    if (i < mine.length && bytes + b > FILE_BYTES) break
    bytes += b
    i--
  }
  return { lines: mine.slice(i), bytes }
}

type Sink = Kept & { session: string; path: string; version: string }

// Module-local, so a hot reload starts from the file: the lines already on disk for this session.
let sink: Promise<Sink | null> | null = null
let sinkSession = ''
let writes: Promise<void> = Promise.resolve()
let toasted = ''

/** slim's own plugin.json version, read once per sink, else `unknown`. */
async function version($: $): Promise<string> {
  try {
    const v = (JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`)) as { version?: unknown }).version
    return typeof v === 'string' && v ? v : 'unknown'
  } catch {
    return 'unknown'
  }
}

async function openSink($: $, session: string): Promise<Sink | null> {
  const dir = logDir(await $.env.get('HOME'), await $.env.get('DOMAINE_LOG_DIR'), session)
  if (dir === null) return null
  const path = `${dir}/slim.jsonl`
  let kept: Kept = { lines: [], bytes: 0 }
  try {
    kept = seedLines(await $.fs.read(path), session)
  } catch {}
  return { ...kept, session, path, version: await version($) }
}

/** Appends the event's line to the session's file; never throws, one toast per session when a write fails. */
async function logLine($: $, ev: SlimEvent): Promise<void> {
  let session = ''
  try {
    session = await $.session.id()
    // A start line reopens the file: the version is new, and a /clear or resume may find lines there.
    if (!sink || sinkSession !== session || ev.kind === 'start') {
      sinkSession = session
      sink = openSink($, session).catch(() => null)
    }
    const s = await sink
    if (!s) return
    // One start line per session, first: a /clear's new id has no session.start, a resumed id may have one on disk.
    if (ev.kind === 'start' && s.lines.some(l => l.includes('"kind":"start"'))) return
    if (ev.kind !== 'start' && !s.lines.length) keep(s, fileLine({ v: 1, atMs: ev.atMs, kind: 'start', text: `slim ${s.version}`, src: 'slim' }, s.version, session))
    keep(s, fileLine(ev, s.version, session))
    const text = `${s.lines.join('\n')}\n`
    // Queued, so an older snapshot never lands after a newer one.
    const w = writes.then(() => $.fs.write(s.path, text))
    writes = w.catch(() => {})
    await w
  } catch (err) {
    if (toasted === session) return
    toasted = session
    const reason = String((err as { message?: unknown } | null)?.message ?? err).replace(/\s+/g, ' ').replace(/^slim: \$\.[\w.]+: /, '').slice(0, 120)
    try {
      $.ui.toast(`slim: event log not written: ${reason}`)
    } catch {}
  }
}

export function registerEventLog(on: On): void {
  // Every slim.events write appends one event (pushEvent), so the newest is the one to log.
  on('state.set', { plugin: 'slim', key: 'events' }, async ($, e, next) => {
    const r = await next(e)
    if ('value' in r && r.value.isSet) {
      const list = e.value as readonly SlimEvent[] | null
      const ev = list?.[list.length - 1]
      if (ev) await logLine($, ev)
    }
    return r
  })
}

files.hooks/mods/guard.ts:
// The spill-read guard: a model's Read of a whole spill (an original or a rows part over the inline
// budget) is denied with a pointer to a windowed Read, view or lookup, since a whale read back raw
// undoes the compression. Windowed Reads, id maps, Grep, Bash and every plugin's own calls (view's and
// lookup's probes among them) pass. Every spill read is recorded as an access line at debug level 1+,
// so --report pairs the recovery with the whale it followed; a denied one is marked and never paired.
import type { EngineInterface, On } from 'claude-code'
import { spillAccess, spillKind } from './channels.ts'
import { buildAccessRun, debugLevel } from './node-hook.ts'

/** A spill at or under this many bytes is read whole without a word: the read channel's own gate. */
export const SPILL_INLINE = 32768

type $ = EngineInterface

export function denyText(path: string, size: number): string {
  return `slim: ${path} is a ${size} B spill — Read it with offset/limit, or call mcp__slim__view({ path, jq }) to narrow it, ` +
    'or mcp__slim__lookup({ path, question }) for one fact'
}

async function record($: $, payload: Record<string, unknown>): Promise<void> {
  try {
    if (debugLevel(await $.env.get('SLIM_DEBUG')) < 1) return
    const { argv, init } = buildAccessRun($.plugin.root, { v: 1, ...payload, cwd: await $.session.cwd() })
    await $.process.run(argv, init)
  } catch {}
}

async function oversize($: $, path: string): Promise<number | null> {
  try {
    const st = await $.fs.stat(path)
    return st.kind === 'file' && st.size > SPILL_INLINE ? st.size : null
  } catch {
    return null
  }
}

export function registerGuard(on: On): void {
  on('tool.call', { tool: /^(?:Read|Bash|Grep)$/ }, async ($, e, next) => {
    if (next.origin.plugin !== 'engine') return next(e)
    const args = e as unknown as Record<string, unknown>
    const hit = spillAccess(String(e.tool), args)
    if (hit === null) return next(e)
    if (hit.tool === 'Read' && args.offset === undefined && args.limit === undefined && args.pages === undefined) {
      const kind = spillKind(hit.paths[0]!)
      if ((kind === 'original' || kind === 'rows') && (await $.env.get('SLIM_SPILL_GUARD')) !== '0') {
        const size = await oversize($, hit.paths[0]!)
        if (size !== null) {
          await record($, { tool: hit.tool, via: hit.via, spills: [hit.paths[0]!], denied: true })
          return { deny: denyText(hit.paths[0]!, size) }
        }
      }
    }
    // Never race next: returning while it is pending aborts the tool beneath.
    const r = await next(e)
    if (r.deny !== undefined || r.isError === true) return r
    await record($, { tool: hit.tool, via: hit.via, spills: hit.paths })
    return r
  })
}

files.hooks/mods/info.ts:
// slim.info: the snapshot that tells another plugin that slim is loaded, which version, and which
// channels it compresses this session; then slim's start line, the first it publishes in a session.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'
import type { SlimChannel, SlimEvent } from '../../types'
import { pushEvent } from './events.ts'

type $ = EngineInterface

const EVENTS = atom({ plugin: 'slim', key: 'events' } as const, [] as SlimEvent[])
const STARTED = atom({ plugin: 'slim', key: 'started' } as const, null as string | null)

/** The channels whose switch is not 0, each switch read by its literal name. */
async function channelsOn($: $): Promise<SlimChannel[]> {
  const off = async (name: Promise<string | undefined>) => (await name) === '0'
  const out: SlimChannel[] = []
  if (!(await off($.env.get('SLIM_MCP')))) out.push('mcp')
  if (!(await off($.env.get('SLIM_BASH')))) out.push('bash')
  if (!(await off($.env.get('SLIM_READ')))) out.push('read')
  const web = !(await off($.env.get('SLIM_WEB')))
  if (web) out.push('webfetch', 'websearch')
  const grep = !(await off($.env.get('SLIM_GREP')))
  if (grep) out.push('grep', 'glob')
  if (!(await off($.env.get('SLIM_AGENT')))) out.push('agent')
  if (!(await off($.env.get('SLIM_ATTACH')))) out.push('attachment')
  if (!(await off($.env.get('SLIM_PROMPT')))) out.push('prompt')
  return out
}

async function version($: $): Promise<string> {
  try {
    const v = (JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`)) as { version?: unknown }).version
    return typeof v === 'string' && v ? v : 'unknown'
  } catch {
    return 'unknown'
  }
}

/** `slim <version>`, once per session id: a repeated session.start writes none. */
async function startLine($: $, v: string): Promise<void> {
  if ((await $.env.get('SLIM_EVENT_LOG')) === '0') return
  const session = await $.session.id()
  if ((await read($, STARTED)) === session) return
  await update($, STARTED, () => session)
  const ev: SlimEvent = { v: 1, atMs: await $.clock.now(), kind: 'start', text: `slim ${v}`, src: 'slim' }
  await update($, EVENTS, l => pushEvent(l, ev))
}

export function registerInfo(on: On): void {
  on('session.start', async ($, e, next) => {
    // One throwing session.start hook skips every slim session.start hook (lookup's registration too).
    try {
      const v = await version($)
      await $.state.set({ plugin: 'slim', key: 'info' }, { v: 1, version: v, channels: await channelsOn($) })
      await startLine($, v)
    } catch {}
    return next(e)
  })
}

files.hooks/mods/intake.ts:
// Every tool result slim reads goes through scripts/slim.cjs here: the result replaced with the core's
// answer, one slim.events entry, the row the ToolResult and ToolGroup lines draw, and a savings toast
// for MCP calls on the main loop. An @-mentioned data file goes the same way, as the read channel's.
import { atom, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'
import type { SlimChannel, SlimEvent } from '../../types'
import { GATES, attachmentEligible, attachmentPath, attachmentShape, candidate, channelOf, floor, guardOf, viewOf } from './channels.ts'
import type { Pre } from './channels.ts'
import { agentPrefix, eventText, pushEvent } from './events.ts'
import {
  alreadySlimIn,
  alreadySlimTexts,
  bareCurl,
  buildErrorRun,
  buildRun,
  bytesSeen,
  debugLevel,
  hostStub,
  omit,
  parseOut,
  plainBytes,
  resultBytes,
  stubBytes,
  textKey,
  toastMs,
  utf8Bytes,
} from './node-hook.ts'

const EVENTS = atom({ plugin: 'slim', key: 'events' } as const, [] as SlimEvent[])

export const DENY_TEXT =
  'slim: a bare curl of a page is turned off here (SLIM_CURL=deny) — for one fact call mcp__slim__lookup({ url, question }); ' +
  'for the page content use WebFetch(url, prompt).'

type $ = EngineInterface

/** The channel's SLIM_<CHANNEL> switch, each read by its literal name. */
async function switchOf($: $, ch: SlimChannel): Promise<string | undefined> {
  switch (ch) {
    case 'mcp': return $.env.get('SLIM_MCP')
    case 'bash': return $.env.get('SLIM_BASH')
    case 'read': return $.env.get('SLIM_READ')
    case 'webfetch':
    case 'websearch': return $.env.get('SLIM_WEB')
    case 'grep':
    case 'glob': return $.env.get('SLIM_GREP')
    case 'agent': return $.env.get('SLIM_AGENT')
    case 'attachment': return $.env.get('SLIM_ATTACH')
    case 'prompt': return $.env.get('SLIM_PROMPT')
  }
}

async function level($: $): Promise<0 | 1 | 2> {
  return debugLevel(await $.env.get('SLIM_DEBUG'))
}

/** Within this many bytes a stub mark or a stats line beside a handle is trusted without the core. */
async function slimBound($: $): Promise<number> {
  return stubBytes(await $.env.get('SLIM_STUB_BYTES')) + 1200
}

/** Asks the core to append the error line: `$.fs` has no append, and the spill root is the core's to resolve. */
async function reportError($: $, channel: string, tool: string, toolUseId: string | undefined, name: string, message: string): Promise<void> {
  try {
    const payload = {
      v: 1,
      channel,
      tool,
      ...(toolUseId !== undefined ? { tool_use_id: toolUseId } : {}),
      cwd: await $.session.cwd(),
      error: { name, message: message.slice(0, 200) },
    }
    const { argv, init } = buildErrorRun($.plugin.root, payload)
    await $.process.run(argv, init)
  } catch {}
}

/** The subagent's type as $.agent.list() names it; undefined when unlisted or the list throws. */
async function agentType($: $, agentId: string): Promise<string | undefined> {
  try {
    return (await $.agent.list()).find(a => a.id === agentId)?.type || undefined
  } catch {
    return undefined
  }
}

export function registerIntake(on: On): void {
  on('tool.call', async ($, e, next) => {
    // Only the model's calls: a plugin's own $.tool.call (lookup's among them) gets the record it asked for.
    if (next.origin.plugin !== 'engine') return next(e)
    const args = e as unknown as Record<string, unknown>
    const tool = String(e.tool)
    if (tool === 'Bash' && /\bcurl\b/.test(String(args.command ?? ''))) {
      if ((await $.env.get('SLIM_CURL')) === 'deny' && bareCurl(String(args.command))) return { deny: DENY_TEXT }
    }

    // Never race next: returning while it is pending aborts what runs beneath.
    const r = await next(e)
    if (r.deny !== undefined) return r
    const ch = channelOf(tool)
    if (ch === null || ch === 'lookup' || ch === 'view') return r

    // Passthroughs the mod can tell alone; the core is spawned for them only to write the report line.
    let pre: Pre | null = null
    let bytesIn: number
    if (ch === 'mcp') {
      if ((await switchOf($, ch)) === '0') return r
      // Already-slim first: a slimmed result can quote the overflow phrase above its own host-file handle.
      const slimmed = alreadySlimIn(r.result, await slimBound($), r.text)
      bytesIn = resultBytes(r.result)
      if (slimmed || hostStub(r.result) === null) {
        pre = r.isError === true ? 'error-shape' : slimmed ? 'already-slim' : bytesIn <= GATES.mcp ? 'size-gate' : null
      }
    } else {
      // Sizes first and pure: a result below the floor costs no env read and writes no line.
      const view = viewOf(ch, r, args)
      if (view === null || !floor(ch, view)) return r
      if ((await switchOf($, ch)) === '0') return r
      bytesIn = view.bytes
      pre = guardOf(ch, view)
      if (pre === null && alreadySlimTexts(view.texts, await slimBound($))) pre = 'already-slim'
      if (pre === null && !candidate(ch, view, plainBytes(await $.env.get('SLIM_PLAIN_BYTES')))) return r
    }
    if (pre !== null && (await level($)) < (pre === 'error-shape' ? 1 : 2)) return r

    const envelope = {
      v: 1,
      channel: ch,
      tool,
      tool_use_id: e.tool_use_id,
      tool_input: omit(e, ['tool', 'tool_use_id', 'agentId']),
      tool_response: pre ? null : r.result,
      is_error: r.isError === true,
      cwd: await $.session.cwd(),
      session_id: await $.session.id(),
      ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
      ...(pre ? { pre, bytes_in: bytesIn } : {}),
    }
    const { argv, init } = buildRun($.plugin.root, envelope)
    let run
    try {
      run = await $.process.run(argv, init)
    } catch (err) {
      await reportError($, ch, tool, e.tool_use_id, 'spawn-rejected', String((err as Error)?.message ?? err))
      return r
    }
    const parsed = parseOut(run)
    if (!parsed.ok) {
      await reportError($, ch, tool, e.tool_use_id, parsed.reason, parsed.message)
      return r
    }
    const out = parsed.out
    if (pre || (out.decision !== 'compressed' && out.decision !== 'stubbed')) return r

    const rec = out.record
    const engine = rec.engine!
    const seen = bytesSeen(rec)
    try {
      await $.state.set({ plugin: 'slim', key: 'rows', id: e.tool_use_id }, { engine, bytesIn: seen, bytesOut: rec.bytes_out })
    } catch {}

    const isSub = e.agentId !== undefined
    const listed = isSub ? await agentType($, e.agentId!) : undefined
    const type = isSub ? (listed ?? 'agent') : undefined
    const decision = out.decision as 'compressed' | 'stubbed'
    const text = eventText(agentPrefix(listed, isSub), tool, decision, engine, seen, rec.bytes_out)
    // A toast per Bash or Read would be noise: the other channels show the row and the group line.
    if (ch === 'mcp' && !isSub && (await $.env.get('SLIM_TOAST')) !== '0') {
      $.ui.toast(text, { timeoutMs: toastMs(await $.env.get('SLIM_TOAST_MS')) })
    }
    if ((await $.env.get('SLIM_EVENT_LOG')) !== '0') {
      try {
        const atMs = await $.clock.now()
        const ev: SlimEvent = {
          v: 1, atMs, kind: 'slim', text, src: 'slim', tool, channel: ch,
          ...(type ? { agentType: type } : {}),
          bytesIn: seen, bytesOut: rec.bytes_out, engine, ms: rec.ms,
        }
        await update($, EVENTS, l => pushEvent(l, ev))
      } catch {}
    }
    // A fresh object: returning `r` itself would make core reuse its own messages verbatim.
    return r.context?.length ? { result: out.result, context: r.context } : { result: out.result }
  })

  // An @-mentioned file reaches the model as the host frames a Read of it. A data file's numbered lines
  // are compressed the way the read channel's are; source and prose pass. The host caches the answer
  // and asks again after a compaction, so the core answers the same text the same way, and the Log
  // line and the report line are written once per content.
  on('prompt.attachment', { type: 'file' }, async ($, e, next) => {
    const d = await next(e)
    const text = d.text
    if (typeof text !== 'string' || utf8Bytes(text) <= GATES.attachment) return d
    try {
      if ((await switchOf($, 'attachment')) === '0') return d
      const path = attachmentPath(text)
      const pre: Pre | null = attachmentEligible(text, path) ? null : 'read-guard'
      if (pre !== null && (await level($)) < 2) return d
      const seenKey = { plugin: 'slim', key: 'seen', id: textKey(text) } as const
      const seen = pre === null && (await $.state.get(seenKey).then(r => r.value === true, () => false))
      const request = {
        v: 1,
        channel: 'attachment',
        tool: 'Attachment',
        tool_input: { type: e.type, origin: e.origin.kind, shape: attachmentShape(text), ...(path !== null ? { path } : {}) },
        tool_response: pre ? null : { text },
        is_error: false,
        cwd: await $.session.cwd(),
        session_id: await $.session.id(),
        ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
        ...(pre ? { pre, bytes_in: utf8Bytes(text) } : {}),
        ...(seen ? { record: false } : {}),
      }
      const { argv, init } = buildRun($.plugin.root, request, 30_000)
      const parsed = parseOut(await $.process.run(argv, init))
      if (!parsed.ok) {
        await reportError($, 'attachment', 'Attachment', undefined, parsed.reason, parsed.message)
        return d
      }
      const out = parsed.out
      const res = out.result as { text?: unknown } | undefined
      if (pre || (out.decision !== 'compressed' && out.decision !== 'stubbed') || typeof res?.text !== 'string') return d
      const rec = out.record
      try {
        if (!seen) await $.state.set(seenKey, true)
        if (!seen && (await $.env.get('SLIM_EVENT_LOG')) !== '0') {
          const isSub = e.agentId !== undefined
          const listed = isSub ? await agentType($, e.agentId!) : undefined
          const name = path !== null ? `@${path.slice(path.lastIndexOf('/') + 1)}` : '@file'
          const ev: SlimEvent = {
            v: 1, atMs: await $.clock.now(), kind: 'slim', src: 'slim', tool: 'Attachment', channel: 'attachment',
            text: eventText(agentPrefix(listed, isSub), name, out.decision as 'compressed' | 'stubbed', rec.engine!, bytesSeen(rec), rec.bytes_out),
            ...(isSub ? { agentType: listed ?? 'agent' } : {}),
            bytesIn: bytesSeen(rec), bytesOut: rec.bytes_out, engine: rec.engine!, ms: rec.ms,
          }
          await update($, EVENTS, l => pushEvent(l, ev))
        }
      } catch {}
      return { text: res.text }
    } catch {
      return d
    }
  })
}

